  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.sum()"
}

{
  "name": "pairwise_cost_gap_preference",
  "intuition": "This loss directly encourages the model to prefer pairs where the cost difference (cost_gap) aligns with the desired preference, penalizing cases where the model's ranking contradicts the cost order. It leverages the log-sigmoid of the scaled cost gap to produce a smooth, differentiable signal that emphasizes the correct ordering, thus improving preference learning in RL4CO scenarios.",
  "pseudocode": "loss = -mean(logsigmoid((log_prob_w - log_prob_l) * scale * cost_gap))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "cost",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "preference",
    "other_hparams": "scale=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    scale = float(extra.get('scale', 1.0))\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap = batch['cost_gap']\n    # Compute pairwise preference signal\n    diff = (log_prob_w - log_prob_l) * scale * cost_gap\n    loss = -ops.mean(ops.logsigmoid(diff))\n    return loss"
}

