  },
  "code": "def generated_loss(batch, model_output, extra):\n    import torch\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', torch.ones_like(lpw))\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    gap = advantage_w - advantage_l\n    loss = weight * (torch.exp(-alpha * gap) - 1.0)\n    return loss.mean()"
}

