{
  "name": "loss_logsigmoid_003_advantage_scaled_margin_weighted_repaired",
  "intuition": "Fix missing advantage_gap by safely defaulting to zeros; preserve original multiplicative interaction and stable clamp to ensure valid forward and backward passes.",
  "pseudocode": "adv_gap = batch.get('advantage_gap', zeros)\nscaled_diff = alpha * scale * (log_prob_w - log_prob_l)\ninteraction = scaled_diff * (1 + margin * adv_gap)\nx = clamp(interaction, -20, 20)\nloss = sum(-logsigmoid(x) * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_gap",
    "link_family": "logsigmoid",
