  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    zeros = lpw.new_zeros(lpw.shape)\n    adv_gap = batch.get('advantage_gap', zeros)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    margin = float(extra.get('hyperparams', {}).get('margin', 0.3))\n    scaled_diff = alpha * scale * (lpw - lpl)\n    interaction = scaled_diff * (1.0 + margin * adv_gap)\n    x = ops.clamp(interaction, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    loss = loss * weight\n    return loss.sum()"
}

{
  "name": "pairwise_preference_margin_loss",
  "intuition": "This loss compares pairwise log probabilities to enforce a preference ordering, penalizing cases where the less preferred option has higher probability. By incorporating a margin and pairwise signals like cost_gap, it encourages the model to assign higher likelihood to better options, leading to consistent preference learning in RL4CO.",
  "pseudocode": "loss = sum(max(0, margin + log_prob_l - log_prob_w) * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "sum",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "optional_margin=0.1"
  },
  "operators_used": ["logsigmoid", "max", "clamp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    margin = float(extra.get('optional_margin', 0.1))\n    cost_gap = batch['cost_gap']\n    x = margin + lpl - lpw\n    x = ops.clamp(x, 0.0, float('inf'))\n    loss = ops.max(x, 0.0)\n    if weight is not None:\n        loss = loss * weight\n    return loss.sum()"
}

{
  "name": "loss_pairwise_ranknet_advantage_logsumexp_agg",
  "intuition": "A pairwise ranking loss inspired by RankNet using advantage signals to weight the logistic loss of score differences, aggregated with log-sum-exp for smooth max approximation instead of mean.",
  "pseudocode": "prob = sigmoid(lpw - lpl)\nweighted_loss = -weight * cost_gap * log(prob + eps)\nloss = ops.reduce_logsumexp(weighted_loss, dim=0)",
  "hyperparams": {
    "paradigm_family": "pairwise_probabilistic",
    "signal_family": "cost_gap",
    "link_family": "sigmoid",
    "agg_family": "logsumexp",
    "constraint_family": "none"
  },
  "operators_used": ["sigmoid", "log", "mul", "reduce_logsumexp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_b", "cost_a"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-12\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    zeros = lpw.new_zeros(lpw.shape)\n    cost_gap = batch.get('cost_gap', batch.get('cost_b', zeros) - batch.get('cost_a', zeros))\n    diff = lpw - lpl\n    prob = ops.sigmoid(diff)\n    log_prob = ops.log(prob.clamp(min=eps))\n    loss = -weight * cost_gap * log_prob\n    return ops.reduce_logsumexp(loss, dim=0)"
}

{
  "name": "pairwise_cost_gap_preference_logsigmoid_weighted_mean",
  "intuition": "This loss uses the pairwise cost gap preference signal with a logsigmoid link and a weighted mean aggregation over the batch to stabilize gradients and avoid unsupported ops.",
  "pseudocode": "losses = -logsigmoid((log_prob_w - log_prob_l) * scale * cost_gap) * weight\nloss = sum(losses) / sum(weight)",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "cost",
    "link_family": "sigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "preference"
  },
  "operators_used": [
    "logsigmoid"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "cost_gap",
      "weight"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    scale = float(extra.get('scale', 1.0))\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    cost_gap = batch.get('cost_gap', batch.get('cost_b', lpw.new_zeros(lpw.shape)) - batch.get('cost_a', lpw.new_zeros(lpw.shape)))\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    x = (lpw - lpl) * scale * cost_gap\n    losses = -ops.logsigmoid(x) * weight\n    total_weight = weight.sum().clamp(min=eps)\n    loss = losses.sum() / total_weight\n    return loss"
}

