{
  "name": "pairwise_softplus_rank_loss",
  "intuition": "This loss combines advantage_gap and cost_gap signals to create a smooth pairwise ranking objective. By applying a softplus function to the negative margin, it emphasizes pairs where the weighted difference in log probabilities aligns with the combined quality gaps, promoting better ranking consistency while maintaining smooth gradient signals for optimization.",
  "pseudocode": "combined_gap = advantage_gap * 0.7 + cost_gap * 0.3\nmargin = alpha * (log_prob_w - log_prob_l) - beta * combined_gap.detach()\nloss = ops.softplus(-margin)\nreturn loss.sum() / (weight.sum() + 1e-8)",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_cost_combined",
    "link_family": "softplus",
    "agg_family": "weighted_mean",
    "constraint_family": "monotonic_ranking",
    "other_hparams": ""
  },
  "operators_used": ["softplus"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    advantage_gap = batch['advantage_gap']\n    cost_gap = batch['cost_gap']\n    alpha = float(extra.get('alpha', 1.0))\n    beta = float(extra.get('beta', 1.0))\n    combined_gap = 0.7 * advantage_gap + 0.3 * cost_gap\n    margin = alpha * (lpw - lpl) - beta * combined_gap.detach()\n    loss = ops.softplus(-margin)\n    if weight is not None:\n        weighted_loss = loss * weight\n        total_weight = weight.sum()\n        return weighted_loss.sum() / (total_weight + 1e-8)\n    else:\n        return loss.mean()"
}
